import asyncio
from pydantic_settings import BaseSettings
import mcp
class Settings(BaseSettings):
    MODEL_NAME: str
    MODEL_HOST: str = '127.0.0.1'
    MODEL_PORT: int = 8000
    MODEL_TIMEOUT: int = 120
    def __init__(self):
        super().__init__()
        self.MODEL_URL = f'graceful://graceful-{self.MODEL_NAME}@{self.MODEL_HOST}:{self.MODEL_PORT}/{self.MODEL_TIMEOUT}'
        self.client = mcp.Client.from_url(self.MODEL_URL)

@mcp.server()
def run(
    client,
):
    """Run the client with the given client."""
    try:
        with client:
            yield client
    except Exception as e:
        print(f"Error in run(): {e}")

async def main():
    client = mcp.Client.from_url(
        f'graceful://graceful-{Settings().MODEL_NAME}@{Settings().MODEL_HOST}:{Settings().MODEL_PORT}/{Settings().MODEL_TIMEOUT}"
    )

    # Create a tool for each available MCP tool
    for tool in client.registry:
        client.register_tool(tool.name)

if __name__ == "__main__":
    asyncio.run(main())

